+TEST_CASE("RaBitQ row training supports reusable non-contiguous scratch", "[lite-rabitq]") {
+    namespace codec = vsag::lite::detail::rabitq;
+    for (const uint64_t dim : {1ULL, 17ULL, 128ULL}) {
